// Verifies datasets against description_datasets.md, from files or from memory.
//
//   ./verify_datasets [--dir DIR] [--verbose]
//   ./verify_datasets --in-memory [--rows N] [--columns M] [--elements 4,8]
//                     [--compare-files] [--verbose]
//
// File mode reads a generated directory. In-memory mode generates the same
// catalog through TslDatasetSource and verifies it without touching the disk,
// which is how a benchmark consumes it; --compare-files additionally requires the
// generated bytes to equal the stored ones, proving the two paths agree.
//
// For every dataset this recomputes the descriptor from the values and checks
// three independent things:
//
//   1. the container round-trips: header fields and payload checksum match the
//      manifest;
//   2. the recomputed descriptor is identical to the one recorded at generation
//      time, so nothing was lost between the generator's array and the file;
//   3. the descriptor satisfies the closed-form expectations of the shape, which
//      are derived from the spec parameters rather than from the data.
//
// Exits non-zero if any dataset fails.

#include <algorithm>
#include <cstdlib>
#include <exception>
#include <iomanip>
#include <iostream>
#include <map>
#include <string>
#include <vector>

#include "dataset_catalog.hpp"
#include "dataset_descriptor.hpp"
#include "dataset_file.hpp"
#include "dataset_manifest.hpp"
#include "dataset_source.hpp"

#ifndef TSL_DATASET_DEFAULT_DIR
#define TSL_DATASET_DEFAULT_DIR "data"
#endif

namespace {

struct Result {
  std::string id;
  std::string shape;
  int section = 0;
  bool container_ok = false;
  bool descriptor_ok = false;
  std::vector<TslCheck> checks;
  TslDatasetDescriptor measured;
  std::string mismatch;

  auto failed_checks() const -> std::size_t {
    return static_cast<std::size_t>(
      std::count_if(checks.begin(), checks.end(), [](TslCheck const & check) {
        return !check.passed();
      })
    );
  }
  auto ok() const -> bool {
    return container_ok && descriptor_ok && failed_checks() == 0;
  }
};

// In-memory: generate through the source the benchmark would use, then run the
// same descriptor and expectation checks. Optionally require the generated bytes
// to match a stored file, which ties the two paths together.
template <class DataType>
auto verify_in_memory(TslDatasetSpec const & spec, TslDatasetSource<DataType> & source,
                      std::string const & compare_dir) -> Result {
  Result result;
  result.id = spec.id;
  result.shape = tsl_shape_name(spec.shape);
  result.section = tsl_shape_section(spec.shape);

  auto const columns = source.pristine(spec);
  result.measured = tsl_describe_dataset(*columns);
  result.checks = tsl_expected_checks(spec, result.measured);
  result.descriptor_ok = true;
  result.container_ok = true;

  if (!compare_dir.empty()) {
    auto const path = compare_dir + "/" + spec.id + ".bin";
    auto const header = tsl_dataset_read_header(path);
    auto const stored = tsl_dataset_read<DataType>(path, header);
    auto const [column, row] = tsl_first_difference(stored, *columns);
    result.container_ok = column == stored.size();
    if (!result.container_ok) {
      result.mismatch = "generated bytes differ from " + spec.id + ".bin at column " +
                        std::to_string(column) + ", row " + std::to_string(row);
    }
  }

  // The reference image is part of what a consumer gets from the source, so
  // exercise it here too: it must be ordered and a permutation of the input.
  for (auto direction : {TslDirection::Ascending, TslDirection::Alternating}) {
    auto const image = source.reference(spec, direction);
    auto const ascending = tsl_direction_ascending(direction, image->size());
    tsl_require_ordered(*image, ascending);
  }
  return result;
}

template <class DataType>
auto verify_one(TslManifestEntry const & entry, TslDatasetHeader const & header,
                std::string const & path) -> Result {
  Result result;
  result.id = entry.id;
  result.shape = entry.shape;
  result.section = tsl_shape_section(tsl_shape_from_name(entry.shape));

  auto const columns = tsl_dataset_read<DataType>(path, header);
  result.container_ok =
    header.rows == entry.rows &&
    header.columns == entry.columns &&
    header.element_bytes == entry.element_bytes &&
    header.seed == entry.seed &&
    tsl_dataset_checksum(columns) == entry.checksum;

  result.measured = tsl_describe_dataset(columns);
  result.descriptor_ok = tsl_serialize_descriptor(result.measured) == entry.measured;
  result.checks = tsl_expected_checks(entry.spec(), result.measured);
  return result;
}

}  // namespace

int main(int argc, char ** argv) try {
  std::string directory = TSL_DATASET_DEFAULT_DIR;
  bool verbose = false;
  bool in_memory = false;
  bool compare_files = false;
  std::size_t rows = 262144;
  std::size_t columns = 3;
  std::vector<std::size_t> element_bytes{4, 8};
  for (int index = 1; index < argc; ++index) {
    std::string const argument = argv[index];
    if (argument == "--dir" && index + 1 < argc) {
      directory = argv[++index];
    } else if (argument == "--rows" && index + 1 < argc) {
      rows = std::stoull(argv[++index]);
    } else if (argument == "--columns" && index + 1 < argc) {
      columns = std::stoull(argv[++index]);
    } else if (argument == "--elements" && index + 1 < argc) {
      element_bytes.clear();
      std::string const text = argv[++index];
      std::size_t start = 0;
      while (start <= text.size()) {
        auto const comma = text.find(',', start);
        auto const token = text.substr(start, comma - start);
        if (!token.empty()) {
          element_bytes.push_back(std::stoull(token));
        }
        if (comma == std::string::npos) {
          break;
        }
        start = comma + 1;
      }
    } else if (argument == "--in-memory") {
      in_memory = true;
    } else if (argument == "--compare-files") {
      compare_files = true;
      in_memory = true;
    } else if (argument == "--verbose") {
      verbose = true;
    } else if (argument == "--help" || argument == "-h") {
      std::cout << "usage: verify_datasets [--dir DIR] [--verbose]\n"
                   "       verify_datasets --in-memory [--rows N] [--columns M] "
                   "[--elements 4,8] [--compare-files]\n";
      return 0;
    } else {
      throw std::runtime_error("unknown argument: " + argument);
    }
  }

  std::vector<Result> results;
  if (in_memory) {
    TslDatasetSource<std::uint32_t> source32;
    TslDatasetSource<std::uint64_t> source64;
    std::vector<TslDatasetSpec> specs;
    for (auto width : element_bytes) {
      for (auto const & spec : tsl_default_catalog(rows, columns, width)) {
        specs.push_back(spec);
      }
    }
    std::cout << "verifying " << specs.size() << " datasets generated in memory"
              << " (rows=" << rows << ", columns=" << columns << ")"
              << (compare_files ? " against the files in " + directory : "") << "\n\n";
    results.reserve(specs.size());
    for (auto const & spec : specs) {
      auto const compare_dir = compare_files ? directory : std::string{};
      results.push_back(spec.element_bytes == 4
        ? verify_in_memory<std::uint32_t>(spec, source32, compare_dir)
        : verify_in_memory<std::uint64_t>(spec, source64, compare_dir));
    }
    std::cout << "  source cache: " << source32.generated() + source64.generated()
              << " images generated, " << source32.served_from_cache() + source64.served_from_cache()
              << " served from cache, "
              << (source32.resident_bytes() + source64.resident_bytes()) / (1024 * 1024)
              << " MiB resident\n\n";
  } else {
    auto const entries = tsl_read_manifest_tsv(directory + "/manifest.tsv");
    std::cout << "verifying " << entries.size() << " datasets in " << directory << "\n\n";
    results.reserve(entries.size());
    for (auto const & entry : entries) {
      auto const path = directory + "/" + entry.file;
      auto const header = tsl_dataset_read_header(path);
      results.push_back(header.element_bytes == 4
        ? verify_one<std::uint32_t>(entry, header, path)
        : verify_one<std::uint64_t>(entry, header, path));
    }
  }

  // Per-dataset report, grouped the way the document is.
  int current_section = -1;
  for (auto const & result : results) {
    if (result.section != current_section) {
      current_section = result.section;
      std::cout << "-- section " << current_section << " ------------------------------------\n";
    }
    auto const & measured = result.measured;
    std::cout << (result.ok() ? "  PASS  " : "  FAIL  ")
              << std::left << std::setw(50) << result.id << std::right;
    std::cout << " D=[";
    for (std::size_t level = 0; level < measured.distinct_prefixes.size(); ++level) {
      std::cout << (level == 0 ? "" : ",") << measured.distinct_prefixes[level];
    }
    std::cout << "] R=[";
    for (std::size_t level = 0; level < measured.tied_rows.size(); ++level) {
      std::cout << (level == 0 ? "" : ",")
                << std::fixed << std::setprecision(2)
                << static_cast<double>(measured.tied_rows[level]) / static_cast<double>(measured.rows);
    }
    std::cout << "] W=" << std::setprecision(3) << measured.weighted_work / 1e6 << "M"
              << " runs=" << measured.ascending_runs
              << " tau=" << std::setprecision(3) << measured.kendall_normalized
              << " ldisp=" << std::setprecision(0) << measured.mean_displacement
              << " phi(C=64)=";
    if (measured.leaf_ranges[1] == 0) {
      std::cout << "-";  // no range of that size was submitted at all
    } else {
      std::cout << std::setprecision(2) << measured.leaf_fill_ratio[1];
    }
    std::cout << '\n';

    if (!result.container_ok) {
      std::cout << "          " << (result.mismatch.empty()
        ? "container mismatch (header or checksum)" : result.mismatch) << '\n';
    }
    if (!result.descriptor_ok) {
      std::cout << "          recomputed descriptor differs from the manifest\n";
    }
    for (auto const & check : result.checks) {
      if (!check.passed() || verbose) {
        std::cout << (check.passed() ? "          ok   " : "          BAD  ")
                  << std::left << std::setw(40) << check.name << std::right
                  << " expected " << std::setprecision(6) << check.expected
                  << ", measured " << check.actual;
        if (check.tolerance > 0.0) {
          std::cout << " (tolerance " << check.tolerance << ")";
        }
        std::cout << '\n';
      }
    }
  }

  auto const failures = static_cast<std::size_t>(
    std::count_if(results.begin(), results.end(), [](Result const & result) {
      return !result.ok();
    })
  );
  std::size_t total_checks = 0;
  for (auto const & result : results) {
    total_checks += result.checks.size();
  }
  std::cout << "\n" << (failures == 0 ? "OK" : "FAILED") << ": " << results.size() - failures
            << "/" << results.size() << " datasets passed, " << total_checks
            << " shape expectations evaluated\n";
  return failures == 0 ? 0 : 1;
} catch (std::exception const & error) {
  std::cerr << "verify_datasets failed: " << error.what() << '\n';
  return 1;
}
